package co.nexus.research;
import java.util.*;
import static co.nexus.research.CognitiveCore.Action.*;
/** Procedural local simulator, no external input. */
public final class CognitiveArena {
 public int pos,energy=2,kits,health=100,steps,tags;public boolean done,won,vehicle;
 public final int goal,resource,kit,mount,beacon;private final Random rng;private boolean energyTaken,kitTaken,tracked,read,interacted;private final boolean[] visited=new boolean[64];public String event="Inicio";
 public CognitiveArena(long seed){rng=new Random(seed);List<Integer> cells=new ArrayList<>();for(int i=1;i<64;i++)cells.add(i);Collections.shuffle(cells,rng);goal=cells.get(0);resource=cells.get(1);kit=cells.get(2);mount=cells.get(3);beacon=cells.get(4);visited[0]=true;}
 int distance(int a,int b){return Math.abs(a/8-b/8)+Math.abs(a%8-b%8);}
 int target(){return energy==0&&!energyTaken?resource:health<65&&kits==0&&!kitTaken?kit:!interacted?beacon:goal;}
 int risk(){return distance(pos,beacon)<=2&&!interacted?1:0;}
 public CognitiveCore.Observation observe(){float[] s=new float[128];s[0]=health/100f;s[1]=energy/5f;s[2]=kits/2f;s[3]=risk();s[4]=tracked?1:0;s[5]=!energyTaken&&pos==resource?1:0;s[6]=pos==mount?1:0;s[7]=pos==beacon?1:0;s[8]=1-distance(pos,target())/14f;s[9]=steps/80f;s[10]=vehicle?1:0;s[11]=read?1:0;s[12]=interacted?1:0;s[13]=pos%8/7f;s[14]=pos/8/7f;for(int i=0;i<64;i++)s[16+i]=visited[i]?1:0;
 EnumSet<CognitiveCore.Action> a=EnumSet.of(OBSERVE,SCAN,EXPLORE,MOVE,PLAN);if(pos==resource&&!energyTaken)a.add(GET_ENERGY);if(pos==kit&&!kitTaken)a.add(GET_KIT);if(kits>0&&health<100)a.add(RECOVER);if(risk()>0)a.add(SHELTER);if(pos==beacon&&!interacted){if(!tracked)a.add(TRACK);if(tracked&&energy>0)a.add(TAG);if(!read)a.add(READ);if(read)a.add(INTERACT);}if(energy>0&&energy<5)a.add(RECHARGE);if(pos==mount&&!vehicle)a.add(DRIVE);if(vehicle)a.add(EXIT);return new CognitiveCore.Observation(s,a);}
 private void toward(int t){if(pos%8!=t%8)pos+=Integer.signum(t%8-pos%8);else if(pos/8!=t/8)pos+=8*Integer.signum(t/8-pos/8);}
 public float[] step(CognitiveCore.Action a){if(done||!observe().allowed.contains(a))throw new IllegalArgumentException("Invalid action");int before=distance(pos,target()),oldHp=health;boolean was=visited[pos];float utility=.12f,info=.05f,cost=.10f;switch(a){case MOVE:toward(target());if(vehicle)toward(target());utility=.45f;break;case EXPLORE:int[] offsets={-8,8,-1,1};int d=offsets[rng.nextInt(4)],n=pos+d;if(n>=0&&n<64&&(Math.abs(d)==8||n/8==pos/8))pos=n;utility=.3f;break;case SCAN:case OBSERVE:info=was?.15f:.6f;break;case GET_ENERGY:energy=5;energyTaken=true;utility=.95f;break;case GET_KIT:kits=2;kitTaken=true;utility=.85f;break;case RECOVER:kits--;health=Math.min(100,health+35);utility=.9f;cost=.35f;break;case SHELTER:toward(goal);utility=.55f;break;case TRACK:tracked=true;utility=.65f;info=.85f;break;case TAG:energy--;tags++;utility=.8f;cost=.4f;break;case RECHARGE:energy++;cost=.25f;utility=.45f;break;case READ:read=true;info=.95f;utility=.75f;break;case INTERACT:interacted=true;utility=1;break;case DRIVE:vehicle=true;utility=.65f;break;case EXIT:vehicle=false;utility=.25f;break;case PLAN:info=.2f;break;}
 if(!visited[pos]){visited[pos]=true;info=Math.max(info,.65f);}if((a==MOVE||a==EXPLORE)&&distance(pos,target())<before)utility=Math.max(utility,.75f);if(risk()>0&&a!=SHELTER&&a!=INTERACT&&rng.nextFloat()<.25f)health=Math.max(0,health-8);steps++;won=pos==goal&&interacted;done=won||health==0||steps>=80;if(won)utility=1;if(health==0)utility=0;event=a.name()+" | "+(won?"Objetivo completado":done?"Fin del episodio":"En curso");return new float[]{utility,Math.max(0,Math.min(1,health/100f-(oldHp>health?.15f:0))),cost,info};}
}
